def icon(name, cls='ic'):
    d = PATHS.get(name) or PATHS['star']
    return Markup(f'<svg class="{cls}" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="{d}"/></svg>')


def sport(t):
    t = (t or '').lower()
    if 'ride' in t or 'cycling' in t:
        return icon('bike')
    if 'run' in t:
        return icon('run')
    if 'swim' in t:
        return icon('swim')
    if 'hike' in t:
        return icon('hiking')
    if 'walk' in t:
        return icon('walk')
    return icon('medal')


WEATHER = {
    'clear-night': 'weather-night', 'cloudy': 'weather-cloudy', 'exceptional': 'alert', 'fog': 'weather-fog',
    'hail': 'weather-hail', 'lightning': 'weather-lightning', 'lightning-rainy': 'weather-lightning-rainy',
    'partlycloudy': 'weather-partly-cloudy', 'pouring': 'weather-pouring', 'rainy': 'weather-rainy', 'snowy': 'weather-snowy',
    'snowy-rainy': 'weather-snowy-rainy', 'sunny': 'weather-sunny', 'windy': 'weather-windy', 'windy-variant': 'weather-windy',
}


def weather(condition):
    return icon(WEATHER.get((condition or '').lower(), 'weather-cloudy'))
